KITTI_CAM = DATA / 'kitti/sync/image_02_0000000000.png'

def cm(w, h):
    return (w / 2.54, h / 2.54)

def save(fig, name):
    fig.savefig(OUT / f'{name}.svg', format='svg', facecolor='white', bbox_inches='tight', pad_inches=0.04)
    plt.close(fig)

def bare(ax):
    ax.set_xticks([])
    ax.set_yticks([])
    for s in ax.spines.values():
        s.set_visible(False)

def box(ax, x, y, w, h, fc, ec, text=None, fs=11, tc=None, bold=False, ls='-', r=0.02, lw=1.6):
    p = FancyBboxPatch((x, y), w, h, boxstyle=f'round,pad=0,rounding_size={r}', fc=fc, ec=ec, lw=lw, ls=ls)
    ax.add_patch(p)
    if text:
        ax.text(x + w / 2, y + h / 2, text, ha='center', va='center', fontsize=fs, color=tc or C['text'], fontweight='bold' if bold else 'normal')

def arrow(ax, x0, y0, x1, y1, color, lw=1.8, ls='-'):
    ax.annotate('', (x1, y1), (x0, y0), arrowprops=dict(arrowstyle='-|>', color=color, lw=lw, ls=ls, shrinkA=0, shrinkB=0, mutation_scale=12))

def aisle():
    fig, ax = plt.subplots(figsize=cm(8.4, 4.6))
    fig.subplots_adjust(0.01, 0.01, 0.99, 0.99)
    ax.set_xlim(-0.5, 1.7)
    ax.set_ylim(-0.75, 0.75)
    bare(ax)
    ax.add_patch(Rectangle((-0.5, 0.45), 1.6, 0.16, fc=C['slate_l'], ec=C['slate'], lw=1.2))
    ax.add_patch(Rectangle((-0.5, -0.61), 1.6, 0.16, fc=C['slate_l'], ec=C['slate'], lw=1.2))
    ax.text(0.3, 0.53, 'rack', ha='center', va='center', fontsize=10, color=C['slate'])
    ax.text(0.3, -0.53, 'rack', ha='center', va='center', fontsize=10, color=C['slate'])
    ax.add_patch(Rectangle((-0.42, -0.15), 0.42, 0.3, fc=C['permit_l'], ec=C['slate'], lw=1.6))
    ax.text(-0.21, 0.0, 'base', ha='center', va='center', fontsize=10.5, fontweight='bold')
    arrow(ax, 0.03, 0.0, 0.3, 0.0, C['slate'], lw=2.2)
    ax.text(0.33, 0.0, '1.5 m/s', ha='left', va='center', fontsize=10.5, fontweight='bold')
    ax.add_patch(plt.Circle((1.3, 0.28), 0.07, fc=C['veto_l'], ec=C['veto'], lw=1.8))
    ax.text(1.4, 0.28, 'worker', ha='left', va='center', fontsize=10.5, color=C['veto'], fontweight='bold')
    arrow(ax, 1.3, 0.2, 1.3, 0.05, C['veto'], lw=1.6)
    dc = 1.1
    ax.plot([dc, dc], [-0.4, 0.4], color=C['text'], lw=1, ls=':')
    ax.text(dc + 0.02, -0.35, 'rack end', ha='left', va='center', fontsize=10)
    ax.annotate('', (dc, -0.3), (0.0, -0.3), arrowprops=dict(arrowstyle='<->', color=C['text'], lw=1.3))
    ax.text(0.55, -0.26, 'clear distance 1.10 m', ha='center', va='bottom', fontsize=10.5)
    ax.text(0.6, 0.67, 'each ms of delay: 1.5 mm of travel', ha='center', va='bottom', fontsize=10.5, color=C['amber'], fontweight='bold')
    save(fig, 'aisle')

def kitti_calib():
    v2c = {}
    for line in (DATA / 'kitti' / 'calib_velo_to_cam.txt').read_text().splitlines():
        k, _, v = line.partition(':')
        v2c[k] = v
    c2c = {}
    for line in (DATA / 'kitti' / 'calib_cam_to_cam.txt').read_text().splitlines():
        k, _, v = line.partition(':')
        c2c[k] = v
    R = np.array(v2c['R'].split(), float).reshape(3, 3)
    T = np.array(v2c['T'].split(), float).reshape(3, 1)
    Rr = np.array(c2c['R_rect_00'].split(), float).reshape(3, 3)
    P = np.array(c2c['P_rect_02'].split(), float).reshape(3, 4)
    return (R, T, Rr, P)

