def inset(step):
    fig, ax = plt.subplots(figsize=cm(9.2, 4.9))
    fig.subplots_adjust(0.03, 0.2, 0.97, 0.97)
    x = np.linspace(-120, 420, 600)
    c_safe, q = (150.0, 120.0)
    est = c_safe + q
    from math import gamma
    nu, s = (2.0, 40.0)
    dens = (1 + ((x - est) / s) ** 2 / nu) ** (-(nu + 1) / 2)
    dens = dens / dens.max()
    ax.plot(x, dens, color=C['propose'], lw=2.2)
    tail = x <= c_safe
    if step >= 2:
        ax.fill_between(x[tail], 0, dens[tail], color=C['veto'], alpha=0.55, lw=0)
        ax.text(60, 0.16, 'residual tail\nand bias', color=C['veto'], fontsize=10, ha='center', fontweight='bold')
    ax.axvline(0, color=C['slate'], lw=2.4)
    ax.text(4, 1.02, 'body', fontsize=10.5, color=C['slate'], fontweight='bold', va='bottom')
    ax.axvline(c_safe, color=C['veto'], lw=1.6, ls='--')
    ax.text(c_safe + 3, 1.02, 'C_safe', fontsize=10.5, color=C['veto'], va='bottom', fontweight='bold')
    ax.axvline(est, color=C['permit'], lw=1.8, ls='--')
    ax.text(est + 3, 1.02, 'C_inset', fontsize=10.5, color=C['permit'], va='bottom', fontweight='bold')
    if step >= 2:
        ax.annotate('', (est, 0.86), (c_safe, 0.86), arrowprops=dict(arrowstyle='<->', color=C['text'], lw=1.4))
        ax.text(c_safe - 6, 0.8, 'measured p99\nresidual', ha='right', va='top', fontsize=10)
    ax.set_xlim(-30, 420)
    ax.set_ylim(0, 1.18)
    ax.set_yticks([])
    ax.set_xticks([])
    for s_ in ('left', 'top', 'right'):
        ax.spines[s_].set_visible(False)
    ax.set_xlabel("distance from the machine's envelope (schematic)", fontsize=10.5)
    save(fig, f'inset_step{step}')

def veto():
    fig, ax = plt.subplots(figsize=cm(14.6, 4.4))
    fig.subplots_adjust(0.17, 0.24, 0.98, 0.97)
    ax.set_xlim(0, 1000)
    ax.set_ylim(-0.4, 2.6)
    ax.set_yticks([0.3, 1.3, 2.2])
    ax.set_yticklabels(['permission\npath', 'lidar\n(20 Hz)', 'vision-language\nmodel (2 Hz)'], fontsize=10)
    for s in ('left', 'top', 'right'):
        ax.spines[s].set_visible(False)
    ax.tick_params(axis='y', length=0)
    ax.set_xlabel('time (ms)', fontsize=10.5)
    for t in np.arange(0, 1000, 500.0):
        ax.barh(2.2, 500.0 - 30, left=t + 15, height=0.45, color=C['propose_l'], ec=C['propose'], ls='--')
        ax.text(t + 500.0 / 2, 2.2, '"clear aisle"', ha='center', va='center', fontsize=10.5, color=C['propose'], fontweight='bold')
    hit = 650
    for t in np.arange(0, 1000, 50.0):
        col = C['veto'] if t >= hit else C['sense']
        ax.plot([t + 50.0 / 2], [1.3], 'o', ms=6.5, color=col)
    ax.text(hit + 60, 1.6, 'return inside the envelope', color=C['veto'], fontsize=10, fontweight='bold', va='bottom', ha='right', bbox=dict(fc='white', ec='none', pad=0.5))
    ax.barh(0.3, hit + 50, left=0, height=0.4, color=C['permit_l'], ec=C['permit'])
    ax.text(330, 0.3, 'admits', ha='center', va='center', fontsize=10.5, color=C['permit'], fontweight='bold')
    ax.barh(0.3, 1000 - hit - 50, left=hit + 50, height=0.4, color=C['veto'])
    ax.text((hit + 50 + 1000) / 2, 0.3, 'halts', ha='center', va='center', fontsize=10.5, color='white', fontweight='bold')
    arrow(ax, hit + 25, 1.12, hit + 50, 0.52, C['veto'])
    save(fig, 'veto')

def lostmis(step=2):
    fig, axs = plt.subplots(1, 2, figsize=cm(14.6, 4.4))
    fig.subplots_adjust(0.02, 0.24, 0.98, 0.84, wspace=0.1)
    x = np.linspace(-80, 120, 400)
    true = 0.0

    def g(mu, s):
        return np.exp(-0.5 * ((x - mu) / s) ** 2)
    for ax, title, col in [(axs[0], 'lost frame: flag raised', C['permit']), (axs[1], 'misdated frame: no flag', C['veto'])]:
        ax.set_yticks([])
        for s in ('left', 'top', 'right'):
            ax.spines[s].set_visible(False)
        ax.set_xlim(-80, 120)
        ax.set_ylim(0, 1.25)
        ax.axvline(true, color=C['text'], lw=1.6)
        ax.text(true - 2, 1.12, 'true position', ha='right', fontsize=10)
        ax.set_title(title, fontsize=11, color=col, fontweight='bold', pad=4)
        ax.set_xlabel('obstacle position (mm)', fontsize=10.5)
    axs[0].plot(x, g(4, 12), color=C['neutral'], lw=1.5, ls='--')
    axs[0].plot(x, 0.62 * g(4, 26), color=C['permit'], lw=2.4)
    axs[0].text(40, 0.5, 'spread grows;\n16.7 ms older', color=C['permit'], fontsize=10)
    off = 39.9
    axs[1].plot(x, g(4, 12), color=C['neutral'], lw=1.5, ls='--')
    axs[1].plot(x, g(off, 8), color=C['veto'], lw=2.4)
    axs[1].annotate('', (off, 0.35), (0, 0.35), arrowprops=dict(arrowstyle='<->', color=C['veto'], lw=1.4))
    axs[1].text(off + 14, 0.65, 'spread shrinks;\n39.9 mm off', color=C['veto'], fontsize=10)
    save(fig, 'lostmis')

def kitti_sat():
    img = np.asarray(Image.open(KITTI_CAM).convert('RGB'))
    gray = np.asarray(Image.open(KITTI_CAM).convert('L'))
    full = 255.0
    sat = gray >= full
    over = img.copy().astype(float) / 255
    over[sat] = [0.86, 0.15, 0.15]
    fig = plt.figure(figsize=cm(14.6, 4.6))
    ax = fig.add_axes([0.0, 0.08, 0.66, 0.9])
    ax.imshow(over, interpolation='bilinear')
    bare(ax)
    ax.text(10, 360, 'red: pixels clipped at 255', color='white', fontsize=10.5, fontweight='bold', va='bottom', bbox=dict(fc=C['veto'], ec='none', pad=1.5))
    ax2 = fig.add_axes([0.73, 0.27, 0.25, 0.68])
    h = np.bincount(gray.ravel(), minlength=256) / gray.size * 100
    ax2.bar(np.arange(255), h[:255], width=1.0, color=C['neutral'], lw=0)
    ax2.bar([254], [h[255]], width=4.0, color=C['veto'], lw=0)
    ax2.set_xlim(0, 262)
    ax2.set_xticks([0, 128, 255])
    ax2.set_yticks([0, 4, 8])
    ax2.set_xlabel('pixel value', fontsize=10)
    ax2.set_ylabel('% of pixels', fontsize=10)
    ax2.text(250, h[255] - 0.3, '7.5%', color=C['veto'], fontsize=10.5, fontweight='bold', ha='right', va='top')
    save(fig, 'kitti_sat')
